$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$out=Join-Path $root '.cache/validation/comp-req-558-diag-host'; New-Item -ItemType Directory -Force $out|Out-Null
$vc=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/2022/BuildTools/VC/Auxiliary/Build/vcvars64.bat'; if(!(Test-Path $vc)){throw 'MSVC unavailable'}
$exe=Join-Path $out 'comp-req-558-diag-host.exe'; $i='/I"'+(Join-Path $root 'app/companion_pendant/platform')+'" /I"'+(Join-Path $root 'third_party/denzic-platform/observability/embedded/c/include')+'" /I"'+(Join-Path $root 'third_party/denzic-platform/device_control/embedded/c/include')+'" /I"'+(Join-Path $root 'third_party/denzic-platform/ota/embedded/c/include')+'"'
$s=(Join-Path $root 'tools/comp_req_558_diag_host.c')+' '+(Join-Path $root 'app/companion_pendant/platform/companion_platform_adapters.c')+' '+(Join-Path $root 'third_party/denzic-platform/observability/embedded/c/src/denzic_diag_log_gatt_v1.c')+' '+(Join-Path $root 'third_party/denzic-platform/device_control/embedded/c/src/denzic_device_control_v1.c')+' '+(Join-Path $root 'third_party/denzic-platform/ota/embedded/c/src/denzic_ota_orchestration_v1.c')
$cmd='call "'+$vc+'" >nul && cl.exe /nologo /Brepro /TC /std:c11 /O2 /W4 /WX /Gy '+$i+' '+$s+' /link /OPT:REF /OUT:"'+$exe+'"'; $log=Join-Path $out 'compile.log'; cmd /d /s /c $cmd 2>&1|Set-Content -Encoding utf8 $log; if($LASTEXITCODE-ne0){throw 'diag compile failed'}
$stdout=(& $exe 2>&1|Out-String).Trim(); $code=$LASTEXITCODE; $r=[ordered]@{schema='companion.comp_req_558.diagnostics.host.v1';status=if($code-eq0){'PASS'}else{'NO_GO'};exit_code=$code;compile_command=$cmd;compile_log_sha256=(Get-FileHash $log -Algorithm SHA256).Hash.ToUpper();executable_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToUpper();stdout=$stdout;stdout_sha256=[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($stdout))).Replace('-','')}; $r|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 (Join-Path $out 'result.json'); if($code-ne0){exit $code}
